style.css:
@-moz-document domain("4devs.com.br") {
body {
    background-color: #212529;
    color: #fff;
}

header {
    background: #212529;
}

.main-sidebar li {
    border-top: 2px solid #515151;
}

.main-sidebar li.active a {
    background: #356d7e;
    color: #dedede;
}

#app-wrapper .app-output .output-group .output-txt {
    border: 2px solid #515151;
}

#wrapper-content {
    background: #212529;
}

#app-wrapper .app-input .input-title, #app-wrapper .app-input .input-subtitle {
    color: #dedede;
    font-weight: 700;
}

#app-wrapper #area_resposta {
    border-top: 1px solid #515151;
}

#app-wrapper .app-output, #app-wrapper .app-input, #app-wrapper .app-header, .main-sidebar li.heading, .main-sidebar li, .main-sidebar li:hover {
    background-color: #2b3035;
    color: #dedede;
}

.header-tools form input {
    color: #fff;
    background-color: #2b3035;
    border: 1px solid #515151;
}

#app-wrapper .app-input .input-group select, #app-wrapper .app-input .input-group select:hover {
    background-color: #2b3035;
    border: 2px solid #515151;
    color: #dedede;
}

/* HIDE */
#__lgpd_bar__, .page-info, .related, .app-info, #app-wrapper .app-input .input-title, .header-nav {
    display: none;
}

#app-wrapper .app-output .output-group .output-subtitle {
    color: #dedede;
}

#app-wrapper .app-input {
    border-top: 2px solid #515151;
    padding: 10px 10px 65px 25px;
}

#app-wrapper .app-input .input-group:nth-of-type(2n) {
    border-left: 1px solid #515151;
}

.api-cta {
    border: 1px solid #515151;
    background: #393f45;
}

.api-cta__title {
    color: #dedede;
}

.api-cta__sub {
    color: #9f9f9f;
}

.main-sidebar li a {
    color: #9f9f9f;
}

.main-sidebar .heading:hover {
    background: #404040;
}

#app-wrapper .app-header .app-title, #app-wrapper .app-header .app-info {
    margin: 0;
    color: #dedede;
}

label {
    color: #dedede;
}

#app-wrapper .app-output .output-group .output-txt {
    color: #dedede;
    background-color: #2b3035;
}
}
